uniform float amzp_amplitude;
uniform float amzp_frequency;
uniform float amzp_seed;
uniform float amzp_smoothness;
uniform float amzp_globalAngle;
uniform float amzp_shakeMode;
uniform float amzp_modeIntensity;
uniform float amzp_xRandAmp;
uniform float amzp_xRandFreq;
uniform float amzp_xWaveAmp;
uniform float amzp_xWaveFreq;
uniform float amzp_xPhase;
uniform float amzp_xBias;
uniform float amzp_yRandAmp;
uniform float amzp_yRandFreq;
uniform float amzp_yWaveAmp;
uniform float amzp_yWaveFreq;
uniform float amzp_yPhase;
uniform float amzp_yBias;
uniform float amzp_decayAmount;
uniform float amzp_decaySpeed;
uniform float amzp_rampAmount;
uniform float amzp_rampSpeed;
uniform float amzp_lowFreqAmp;
uniform float amzp_midFreqAmp;
uniform float amzp_highFreqAmp;
uniform float amzp_springTension;
uniform float amzp_springDamping;
uniform float amzp_springMass;
uniform float amzp_edgeMode;
uniform float amzp_globalMix;
    float hash(float n) {
        return fract(sin(n) * 43758.5453123);
    }
    float catmullRom(float t, float s) {
        float i = floor(t);
        float f = fract(t);
        float a = hash(i - 1.0 + s);
        float b = hash(i + s);
        float c = hash(i + 1.0 + s);
        float d = hash(i + 2.0 + s);
        float f2 = f * f;
        float f3 = f2 * f;
        return (-0.5*a + 1.5*b - 1.5*c + 0.5*d) * f3
             + (a - 2.5*b + 2.0*c - 0.5*d) * f2
             + (-0.5*a + 0.5*c) * f
             + b;
    }
    float bandedNoise(float t, float s, float sm) {
        float low = catmullRom(t * 0.7, s) * 2.0 - 1.0;
        float mid = catmullRom(t * 2.1, s + 50.0) * 2.0 - 1.0;
        float hi1 = catmullRom(t * 5.3, s + 100.0) * 2.0 - 1.0;
        float hi2 = catmullRom(t * 11.7, s + 150.0) * 2.0 - 1.0;
        float hiBlend = mix(hi1, hi2, 0.5) * mix(0.3, 0.15, sm);
        return low * amzp_lowFreqAmp
             + mid * amzp_midFreqAmp * mix(0.5, 0.3, sm)
             + hiBlend * amzp_highFreqAmp;
    }
    float getRand(float amzLocal_time, float freq, float ph, float seedOff) {
        float t = (amzLocal_time + ph) * freq;
        float s = amzp_seed + seedOff;
        return bandedNoise(t, s, amzp_smoothness);
    }
    float getWave(float amzLocal_time, float freq, float ph) {
        return sin((amzLocal_time + ph) * freq * 2.0 * 3.14159265359);
