    float getEnvelope(float amzLocal_time) {
        float env = 1.0;
        if (amzp_decayAmount > 0.00001) {
            env *= mix(1.0, exp(-amzLocal_time * amzp_decaySpeed), amzp_decayAmount);
        }
        if (amzp_rampAmount > 0.00001) {
            env *= mix(1.0, 1.0 - exp(-amzLocal_time * amzp_rampSpeed), amzp_rampAmount);
        }
        return clamp(env, 0.0, 1.0);
    }
    float applySpring(float value, float amzLocal_time, float seedOff) {
        if (amzp_springTension < 0.00001) return value;
        float omega = mix(5.0, 20.0, amzp_springTension);
        float zeta = mix(0.1, 0.9, amzp_springDamping);
        float mass = max(amzp_springMass, 0.1);
        float dampedFreq = omega * sqrt(max(1.0 - zeta * zeta, 0.00001));
        float springOsc = exp(-zeta * omega * amzLocal_time / mass) * sin(dampedFreq * amzLocal_time);
        return value + value * springOsc * amzp_springTension * 0.5;
    }
    float2 applyMode(float2 offset, float amzLocal_time) {
        float md = float(int(amzp_shakeMode));
        float mi = amzp_modeIntensity;
        if (md < 1.5) {
            return offset;
        }
        if (md < 2.5) {
            float driftX = catmullRom(amzLocal_time * 0.3, amzp_seed + 700.0) * 2.0 - 1.0;
            float driftY = catmullRom(amzLocal_time * 0.25, amzp_seed + 710.0) * 2.0 - 1.0;
            float microX = catmullRom(amzLocal_time * 8.0, amzp_seed + 720.0) * 2.0 - 1.0;
            float microY = catmullRom(amzLocal_time * 7.5, amzp_seed + 730.0) * 2.0 - 1.0;
            float breathX = sin(amzLocal_time * 0.8 * 3.14159265359) * 0.08;
            float breathY = cos(amzLocal_time * 0.6 * 3.14159265359) * 0.06;
            offset.x = offset.x * 0.5 + (driftX * 0.3 + microX * 0.08 + breathX) * mi * amzp_amplitude * 0.01;
            offset.y = offset.y * 0.5 + (driftY * 0.3 + microY * 0.08 + breathY) * mi * amzp_amplitude * 0.01;
            return offset;
        }
        if (md < 3.5) {
            float rumbleX = catmullRom(amzLocal_time * 1.5, amzp_seed + 800.0) * 2.0 - 1.0;
            float rumbleY = catmullRom(amzLocal_time * 1.3, amzp_seed + 810.0) * 2.0 - 1.0;
            float spikeX = catmullRom(amzLocal_time * 12.0, amzp_seed + 820.0) * 2.0 - 1.0;
            float spikeY = catmullRom(amzLocal_time * 11.0, amzp_seed + 830.0) * 2.0 - 1.0;
            spikeX = spikeX * spikeX * sign(spikeX);
            spikeY = spikeY * spikeY * sign(spikeY);
            offset.x = offset.x * (1.0 + mi * 0.5) + (rumbleX * 0.4 + spikeX * 0.15) * mi * amzp_amplitude * 0.01;
            offset.y = offset.y * (1.0 + mi * 0.5) + (rumbleY * 0.4 + spikeY * 0.15) * mi * amzp_amplitude * 0.01;
            return offset;
        }
        if (md < 4.5) {
            float whipBase = sin(amzLocal_time * amzp_frequency * 3.14159265359 * 2.0);
            float whipSnap = pow(abs(whipBase), 3.0) * sign(whipBase);
            float whipNoiseX = catmullRom(amzLocal_time * 6.0, amzp_seed + 900.0) * 2.0 - 1.0;
            float whipNoiseY = catmullRom(amzLocal_time * 5.5, amzp_seed + 910.0) * 2.0 - 1.0;
            float angle = amzp_globalAngle * 3.14159265359 / 180.0;
            float whipX = whipSnap * cos(angle) + whipNoiseX * 0.2;
            float whipY = whipSnap * sin(angle) + whipNoiseY * 0.2;
            offset.x = whipX * mi * amzp_amplitude * 0.015;
            offset.y = whipY * mi * amzp_amplitude * 0.015;
            return offset;
        }
        if (md < 5.5) {
            float bounceT = amzLocal_time * amzp_frequency * 1.5;
            float bounceX = abs(sin(bounceT * 3.14159265359)) * exp(-bounceT * 0.3);
            float bounceY = abs(sin(bounceT * 3.14159265359 * 0.8 + 0.5)) * exp(-bounceT * 0.35);
            float dirX = (mod(floor(bounceT), 2.0) == 0.0) ? 1.0 : -1.0;
            float dirY = (mod(floor(bounceT * 0.8), 2.0) == 0.0) ? 1.0 : -1.0;
            float bnX = catmullRom(amzLocal_time * 4.0, amzp_seed + 1000.0) * 2.0 - 1.0;
            float bnY = catmullRom(amzLocal_time * 3.5, amzp_seed + 1010.0) * 2.0 - 1.0;
            offset.x = (bounceX * dirX * mi + bnX * 0.1 * mi) * amzp_amplitude * 0.01;
            offset.y = (bounceY * dirY * mi + bnY * 0.1 * mi) * amzp_amplitude * 0.01;
            return offset;
        }
        if (md < 6.5) {
            float jitX = hash(floor(amzLocal_time * amzp_frequency * 3.0) + amzp_seed + 1100.0) * 2.0 - 1.0;
            float jitY = hash(floor(amzLocal_time * amzp_frequency * 2.8) + amzp_seed + 1110.0) * 2.0 - 1.0;
            float smooth1 = catmullRom(amzLocal_time * 15.0, amzp_seed + 1120.0) * 2.0 - 1.0;
            float smooth2 = catmullRom(amzLocal_time * 14.0, amzp_seed + 1130.0) * 2.0 - 1.0;
            offset.x = mix(jitX, smooth1, amzp_smoothness) * mi * amzp_amplitude * 0.01;
            offset.y = mix(jitY, smooth2, amzp_smoothness) * mi * amzp_amplitude * 0.01;
            return offset;
        }
        if (md < 7.5) {
            float d1 = catmullRom(amzLocal_time * 0.15, amzp_seed + 1200.0) * 2.0 - 1.0;
            float d2 = catmullRom(amzLocal_time * 0.12, amzp_seed + 1210.0) * 2.0 - 1.0;
            float d3 = catmullRom(amzLocal_time * 0.4, amzp_seed + 1220.0) * 2.0 - 1.0;
            float d4 = catmullRom(amzLocal_time * 0.35, amzp_seed + 1230.0) * 2.0 - 1.0;
            offset.x = (d1 * 0.7 + d3 * 0.3) * mi * amzp_amplitude * 0.01;
            offset.y = (d2 * 0.7 + d4 * 0.3) * mi * amzp_amplitude * 0.01;
            return offset;
        }
        if (md < 8.5) {
            float punchDecay = exp(-amzLocal_time * 5.0 * mi);
            float punchX = sin(amzLocal_time * amzp_frequency * 3.14159265359 * 4.0) * punchDecay;
            float punchY = cos(amzLocal_time * amzp_frequency * 3.14159265359 * 3.0 + 0.5) * punchDecay;
            float noiseX = catmullRom(amzLocal_time * 10.0, amzp_seed + 1300.0) * 2.0 - 1.0;
            float noiseY = catmullRom(amzLocal_time * 9.0, amzp_seed + 1310.0) * 2.0 - 1.0;
            offset.x = (punchX + noiseX * 0.15 * punchDecay) * mi * amzp_amplitude * 0.012;
            offset.y = (punchY + noiseY * 0.15 * punchDecay) * mi * amzp_amplitude * 0.012;
            return offset;
        }
        return offset;
    }
    float2 applyEdge(float2 uv, float mode) {
        if (mode < 1.5) {
            return uv;
        } else if (mode < 2.5) {
            return fract(uv);
        } else {
            float2 r = uv;
            r.x = (mod(floor(r.x), 2.0) == 0.0) ? fract(r.x) : 1.0 - fract(r.x);
            r.y = (mod(floor(r.y), 2.0) == 0.0) ? fract(r.y) : 1.0 - fract(r.y);
            return r;
        }
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float t = time;
        float em = float(int(amzp_edgeMode));
        float env = getEnvelope(t);
        float xOff = 0.0;
        if (amzp_xRandAmp > 0.00001) {
            xOff += getRand(t, amzp_frequency * amzp_xRandFreq, amzp_xPhase, 0.0) * amzp_xRandAmp;
        }
        if (amzp_xWaveAmp > 0.00001) {
            xOff += getWave(t, amzp_xWaveFreq, amzp_xPhase) * amzp_xWaveAmp;
        }
        xOff *= amzp_amplitude * 0.01;
        xOff += amzp_xBias * amzp_amplitude * 0.005;
        float yOff = 0.0;
        if (amzp_yRandAmp > 0.00001) {
            yOff += getRand(t, amzp_frequency * amzp_yRandFreq, amzp_yPhase, 100.0) * amzp_yRandAmp;
        }
        if (amzp_yWaveAmp > 0.00001) {
            yOff += getWave(t, amzp_yWaveFreq, amzp_yPhase) * amzp_yWaveAmp;
        }
        yOff *= amzp_amplitude * 0.01;
        yOff += amzp_yBias * amzp_amplitude * 0.005;
        float2 offset = applyMode(float2(xOff, yOff), t);
        offset.x = applySpring(offset.x, t, 0.0);
        offset.y = applySpring(offset.y, t, 50.0);
        offset *= env;
        float angRad = amzp_globalAngle * 3.14159265359 / 180.0;
        float cosA = cos(angRad);
        float sinA = sin(angRad);
        float rX = offset.x * cosA - offset.y * sinA;
        float rY = offset.x * sinA + offset.y * cosA;
        offset = float2(rX, rY);
        float2 shakenUV = uv + offset;
        float outBounds = 1.0;
        if (em < 1.5) {
            outBounds = (shakenUV.x < 0.0 || shakenUV.x > 1.0 || shakenUV.y < 0.0 || shakenUV.y > 1.0) ? 0.0 : 1.0;
        }
        shakenUV = applyEdge(shakenUV, em);
        shakenUV = clamp(shakenUV, 0.0, 1.0);
        float4 original = amzTexture(0, uv);
        float4 shaken = amzTexture(0, shakenUV);
        float3 fin = shaken.rgb * outBounds;
        float finA = shaken.a * outBounds;
        fin = mix(original.rgb, fin, amzp_globalMix);
        finA = mix(original.a, finA, amzp_globalMix);
        fin = clamp(fin, 0.0, 1.0);
        amzOutput = float4(fin, finA);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

